from rules import resolve


def solve(data):
    return resolve(
        data["packages"],
        data["roots"],
        data.get("blocked", {}),
        data.get("pins", {}),
        data.get("features", []),
    )

def resolve(packages, roots, blocked=None, pins=None, features=None):
    if not isinstance(packages, dict) or not isinstance(roots, dict):
        return {"error": "unsatisfiable"}

    blocked = blocked if isinstance(blocked, dict) else {}
    pins = pins if isinstance(pins, dict) else {}
    if not isinstance(features, (list, tuple, set, frozenset)):
        features = []
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def parse_dependency(dep):
        if isinstance(dep, str):
            return dep, None, None
        if not isinstance(dep, dict):
            return None
        feature = dep.get("feature")
        if feature and feature not in features:
            return False
        name = dep.get("name")
        low = dep.get("min")
        high = dep.get("max")
        if not isinstance(name, str):
            return None
        if not isinstance(low, int) or not isinstance(high, int) or low > high:
            return None
        return name, low, high

    def in_range(version, bounds):
        low, high = bounds
        return (low is None or version >= low) and (high is None or version <= high)

    def merge_bounds(old, new):
        old_low, old_high = old
        new_low, new_high = new
        low = old_low
        if new_low is not None and (low is None or new_low > low):
            low = new_low
        high = old_high
        if new_high is not None and (high is None or new_high < high):
            high = new_high
        if low is not None and high is not None and low > high:
            return None
        return low, high

    initial_bounds = {}
    for name, interval in roots.items():
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            return {"error": "unsatisfiable"}
        low, high = interval
        if not isinstance(low, int) or not isinstance(high, int) or low > high:
            return {"error": "unsatisfiable"}
        initial_bounds[name] = (low, high)

    # Pins constrain a package if it is selected, but do not add it to the
    # set of packages that must be installed.
    for name, version in pins.items():
        if not isinstance(version, int):
            return {"error": "unsatisfiable"}
        merged = merge_bounds(
            initial_bounds.get(name, (None, None)),
            (version, version),
        )
        if merged is None:
            return {"error": "unsatisfiable"}
        initial_bounds[name] = merged

    def rows_for(name):
        rows = packages.get(name, [])
        return rows if isinstance(rows, list) else []

    def is_blocked(name, version):
        forbidden = blocked.get(name, [])
        if not isinstance(forbidden, (list, tuple, set, frozenset)):
            return False
        return version in forbidden

    def is_acyclic(assigned):
        graph = {name: [] for name in assigned}
        for name, row in assigned.items():
            deps = row.get("deps", [])
            if not isinstance(deps, list):
                return False
            for dep in deps:
                parsed = parse_dependency(dep)
                if parsed is False:
                    continue
                if parsed is None:
                    return False
                graph[name].append(parsed[0])

        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph[name]:
                if dependency not in graph or not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def upper_bound(assigned):
        bound = []
        for name in names:
            if name in assigned:
                bound.append(assigned[name]["version"])
            else:
                versions = [
                    row["version"] for row in rows_for(name)
                    if isinstance(row, dict)
                    and isinstance(row.get("version"), int)
                    and not is_blocked(name, row["version"])
                ]
                bound.append(max([-1] + versions))
        return tuple(bound)

    def search(assigned, needed, bounds):
        nonlocal best_vector, best_versions

        if best_vector is not None and upper_bound(assigned) <= best_vector:
            return

        unresolved = sorted(needed - assigned.keys())
        if not unresolved:
            if not is_acyclic(assigned):
                return
            vector = tuple(
                assigned[name]["version"] if name in assigned else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: assigned[name]["version"] for name in assigned
                }
            return

        name = unresolved[0]
        if name not in packages:
            return

        low, high = bounds.get(name, (None, None))
        rows = [
            row for row in rows_for(name)
            if isinstance(row, dict)
            and isinstance(row.get("version"), int)
            and in_range(row["version"], (low, high))
            and not is_blocked(name, row["version"])
        ]
        rows.sort(key=lambda row: row["version"], reverse=True)

        for row in rows:
            deps = row.get("deps", [])
            if not isinstance(deps, list):
                continue
            parsed = [parse_dependency(dep) for dep in deps]
            if any(dep is None for dep in parsed):
                continue
            parsed = [dep for dep in parsed if dep is not False]

            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_needed = set(needed)
            next_bounds = dict(bounds)
            valid = True

            for dep_name, dep_low, dep_high in parsed:
                next_needed.add(dep_name)
                merged = merge_bounds(
                    next_bounds.get(dep_name, (None, None)),
                    (dep_low, dep_high),
                )
                if merged is None:
                    valid = False
                    break
                next_bounds[dep_name] = merged
                if dep_name in next_assigned and not in_range(
                    next_assigned[dep_name]["version"], merged
                ):
                    valid = False
                    break

            if valid:
                search(next_assigned, next_needed, next_bounds)

    search({}, set(roots), initial_bounds)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
